	/**
	 * 
	 * @return Resource's RGBA byte array
	 */
	public static byte[] getImageRGBA(Resources res, int resouceId) {
		Bitmap bitmap = BitmapFactory.decodeResource(res, resouceId);
		if (bitmap.getWidth() != 32 || bitmap.getHeight() != 32) {
		}
		return getImageRGBA(bitmap);
	}

	/**
	 * 
	 * @return Bitmap's RGBA byte array
	 */
	public static byte[] getImageRGBA(Bitmap inputBitmap) {
		Config config = inputBitmap.getConfig();
		ByteBuffer buffer;

		Bitmap bitmap;
		/**
		 * if bitmap size is not 32*32 create scaled bitmap
		 */

		if (inputBitmap.getWidth() != 32 || inputBitmap.getHeight() != 32) {
			Log.d(TAG, "bitmap resized to 32x32");
			bitmap = Bitmap.createScaledBitmap(inputBitmap, 32, 32, false);
		} else {
			bitmap = inputBitmap;
		}
		/**
		 * if bitmap is not ARGB_8888 format, copy bitmap with ARGB_8888 format
		 */
		if (!config.equals(Bitmap.Config.ARGB_8888)) {
			Bitmap bitmapARBG = bitmap.copy(Bitmap.Config.ARGB_8888, false);
			buffer = ByteBuffer.allocate(bitmapARBG.getByteCount());
			bitmapARBG.copyPixelsToBuffer(buffer);
			bitmapARBG.recycle();
		} else {
			buffer = ByteBuffer.allocate(bitmap.getByteCount());
			bitmap.copyPixelsToBuffer(buffer);
		}
		return buffer.array();
	}
}

package com.torchandroid.cifardemo.lua;

import android.content.Context;
import android.content.res.AssetManager;
import android.content.pm.ApplicationInfo;

public class LuaManager {

	private final String TAG = "LuaManager";
	private static LuaManager mInstance;

	private long mTorchState;
	static {
		System.loadLibrary("torchdemo");
	}

	private native int getTopResult(long stateLocation, int width, int height,
			byte[] bitmapRGBData);

	private native float testTorchData(long stateLocation);

        public native long initTorch(AssetManager manager, String libdir);

	public native void destroyTorch(long stateLocation);

	public static LuaManager getLuaManager(Context context) {
		if (mInstance == null)
			mInstance = new LuaManager(context);
		return mInstance;
	}

	public int getTopRecognitionResult(int width, int height,
			byte[] bitmapRGBData) {
		return getTopResult(mTorchState, width, height, bitmapRGBData);
	}

	private LuaManager(Context context) {
	    ApplicationInfo info = context.getApplicationInfo();
	    mTorchState = initTorch(context.getAssets(), info.nativeLibraryDir);
	}

	@Override
	protected void finalize() throws Throwable {
		destroyTorch(mTorchState);
		super.finalize();
	}

	public float testTorchData() {
		return testTorchData(mTorchState);
	}
}
